// Extract document content AND the customer contact details we need to
// close the Phase-5 loop (WhatsApp re-upload request).
const item = $input.first().json;
const body = item.body || item;

let documentContent = '';
let imageBase64 = null;
if (body.document_base64) { imageBase64 = body.document_base64; documentContent = 'Image document provided as base64'; }
else if (body.document_text) { documentContent = body.document_text; }
else if (body.text) { documentContent = body.text; }
else { documentContent = JSON.stringify(body); }

// Normalise the WhatsApp chat id the same way the BDC agent does.
let chatId = String(body.chat_id || body.phone || body.whatsapp || '').trim();
if (chatId && !chatId.includes('@')) chatId = chatId.replace(/[^0-9]/g, '') + '@c.us';

// ---- TENANT (18 Sep 2026) -------------------------------------------------
// REPLACES the 2 Sep resolver, which read `body.tenant_id` FIRST and only fell
// back to 'Tenant For JWT User'. On the public `audit-kyc` webhook that order
// let an authenticated user of dealership A post `tenant_id: <B>` and have the
// Emirates ID they just uploaded -- plus every audit_log line and the
// kyc_documents row -- filed under B. n8n writes as service_role, which is
// BYPASSRLS with no auth.uid(), so nothing downstream would have caught it.
// The caller's tenant_id is now never a source. It is only ever a CLAIM, and a
// claim that disagrees with the membership row is refused outright.
//
// Two doors, two rules:
//   * public webhook -- `ReceiveDocument` -> `Verify JWT` ->
//     `Tenant For JWT User` -> `Auth Gate` -> here. The ONLY trusted answer is
//     the tenant_members row for the Supabase user behind the verified JWT.
//     No row, or more than one, means refuse. There is no fallback on this
//     door: a fallback is exactly how an unverifiable caller acquires a
//     dealership, and this door carries identity documents.
//   * internal hop  -- `Called by Another Workflow` -> here. The caller is a
//     sibling workflow (the WhatsApp BDC agent) that already resolved the
//     dealership from the WAHA session the document arrived on; `Auth Gate`
//     never ran, and that is how this node tells the doors apart.
//
// Refusals carry the '[NEXUS-UNATTRIBUTED]' prefix at position 0, the contract
// with the NEXUS Error Handler (iYJkh1kztWxZXDbT): the failed execution is
// filed under the quarantine tenant instead of being appended to some real
// dealership's compliance trail.
const NEXUS_BUILTIN = { 'default': 'fff6a2b5-cfd5-4460-8383-875bc5826de0' };  // ALBA CARS
const NEXUS_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let nexusMap = {};
try { nexusMap = JSON.parse(String($env.NEXUS_TENANT_MAP || '')) || {}; } catch (e) { nexusMap = {}; }
if (!nexusMap || typeof nexusMap !== 'object' || !Object.keys(nexusMap).length) nexusMap = NEXUS_BUILTIN;
const nexusKeys = Object.keys(nexusMap);

// What the caller ASSERTED. Never authoritative; only ever cross-checked.
const claimed = String(body.tenant_id || item.tenant_id || '');

// Which door? `$()` throws for a node that did not run in this execution.
let viaWebhook = true;
try { $('Auth Gate').all(); } catch (e) { viaWebhook = false; }

let tenant = null;
let tenantSource = 'unresolved';

if (viaWebhook) {
  const ids = Array.from(new Set(
    $('Tenant For JWT User').all()
      .map((i) => (i && i.json ? i.json.tenant_id : null))
      .filter(Boolean)
      .map(String)
  ));
  if (ids.length > 1) {
    throw new Error('[NEXUS-UNATTRIBUTED] KYC upload rejected: the authenticated user is a member of ' + ids.length + ' dealerships. This endpoint will not choose one on their behalf.');
  }
  if (ids.length === 0 || !NEXUS_UUID.test(ids[0])) {
    throw new Error('[NEXUS-UNATTRIBUTED] KYC upload rejected: the authenticated user has no tenant_members row. A dealership is never taken from the request body.');
  }
  if (claimed && claimed.toLowerCase() !== ids[0].toLowerCase()) {
    throw new Error('[NEXUS-UNATTRIBUTED] KYC upload rejected: caller asserted tenant_id ' + claimed + ' but is a member of ' + ids[0] + '. tenant_id is not a caller-selectable field.');
  }
  tenant = ids[0];
  tenantSource = 'jwt_tenant_member';
} else {
  if (NEXUS_UUID.test(claimed)) {
    tenant = claimed;
    tenantSource = 'internal_caller';
  } else if (nexusKeys.length === 1 && NEXUS_UUID.test(String(nexusMap[nexusKeys[0]] || ''))) {
    tenant = String(nexusMap[nexusKeys[0]]);
    tenantSource = 'sole_configured_tenant';
  } else {
    throw new Error('[NEXUS-UNATTRIBUTED] KYC upload rejected: the internal caller supplied no resolvable tenant_id and ' + nexusKeys.length + ' dealerships are configured. Refusing rather than filing an identity document under a guess.');
  }
}

return [{ json: {
  documentContent: documentContent,
  imageBase64: imageBase64,
  hasImage: !!imageBase64,
  lead_email: body.lead_email || body.email || null,
  lead_name: body.lead_name || body.name || null,
  chat_id: chatId || null,
  tenant_id: tenant,
  tenant_source: tenantSource
} }];

const response = $input.first().json;

// A failure to OBTAIN an audit is not the same fact as "this is not an identity
// document". They used to collapse into the same output, and the row written
// downstream then asserted, about a real customer's passport, that it was not a
// document at all. Carry the distinction so nothing downstream states a verdict
// the model never gave.
const unavailable = (why) => {
  const r = {
    isIdentityDocument: false,
    auditUnavailable: true,
    fullName: null,
    dateOfBirth: null,
    expiryDate: null,
    documentType: null,
    isValid: false,
    tamperingDetected: false,
    confidenceScore: 0,
    remarks: null
  };
  return [{ json: {
    auditResult: JSON.stringify(r),
    parsed: r,
    auditUnavailable: true,
    auditFailureReason: String(why).slice(0, 300)
  } }];
};

// The vision node now runs with onError:'continueRegularOutput', so a 429 from a
// rate-limited endpoint or a 404 from a data-policy guardrail arrives here as an
// item rather than failing the execution. That is deliberate: a failed execution
// is what used to write the raw base64 of a passport into the execution store.
if (response.error) {
  return unavailable('vision call failed: ' + JSON.stringify(response.error).slice(0, 200));
}
if (!response.choices || !response.choices[0] || !response.choices[0].message) {
  return unavailable('unexpected response shape from the vision endpoint');
}

const content = response.choices[0].message.content || '';

let auditResult;
try {
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  auditResult = JSON.parse(cleaned);
} catch (e) {
  return unavailable('the vision endpoint did not return valid JSON');
}

// Defaults to FALSE on purpose. If the model omits the field, the safe failure is
// silence: the row lands on the compliance screen for a human and nobody is told
// anything. The harm being fixed is this system SPEAKING wrongly, so when in
// doubt it must not speak.
auditResult.isIdentityDocument = auditResult.isIdentityDocument === true;
auditResult.isValid = auditResult.isValid === true;
auditResult.tamperingDetected = auditResult.tamperingDetected === true;
auditResult.confidenceScore = Number(auditResult.confidenceScore) || 0;
auditResult.auditUnavailable = false;

// PRIVACY. 'remarks' is the one field the model writes freely, and it is the one
// field that can echo back whatever it read off the document -- full name, date
// of birth, ID number. It is clamped here and, from this point on, it reaches
// only kyc_documents. It no longer reaches the customer's WhatsApp message and it
// no longer reaches communication_logs, which the BDC agent reads back into a
// third-party model on every later turn of the conversation.
auditResult.remarks = (auditResult.remarks == null)
  ? null
  : String(auditResult.remarks).slice(0, 300);

return [{ json: {
  auditResult: JSON.stringify(auditResult),
  parsed: auditResult,
  auditUnavailable: false,
  auditFailureReason: null
} }];

const p = $('Prepare Document').first().json;
return [{ json: {
  status: 'APPROVED',
  message: 'KYC document is valid and verified.',
  details: $json.auditResult,
  parsed: $json.parsed,
  lead_email: p.lead_email,
  lead_name: p.lead_name,
  chat_id: p.chat_id
} }];

const p = $('Prepare Document').first().json;
return [{ json: {
  status: 'REJECTED',
  message: 'KYC document failed validation or tampering was detected.',
  details: $json.auditResult,
  parsed: $json.parsed,
  lead_email: p.lead_email,
  lead_name: p.lead_name,
  chat_id: p.chat_id
} }];

// Phase 5: decide whether to ask the customer to re-upload, or give up and
// escalate to a human. Attempts are counted from communication_logs so the loop
// survives restarts and cannot run forever.
//
// PRIVACY. This node used to build the customer-facing message out of
// parsed.remarks -- free text written by the vision model. If the model echoed
// what it read off the document, the customer's own name, date of birth or ID
// number was messaged back over WhatsApp AND written into communication_logs.
// That table is not the right home for it: whatsapp_bdc_ai_agent's 'Fetch Thread
// History' selects `message` from it and feeds the rows to the BDC agent, so
// anything landing there is re-sent to a third-party model on every subsequent
// turn, and nexus_retention_purge never cleans that table.
//
// The reason shown to the customer now comes from a closed vocabulary below,
// chosen only from booleans and a number. No model-authored string is
// interpolated into anything the customer sees or anything that is logged.
const MAX_ATTEMPTS = 3;
const rej = $('Rejected').first().json;

const rows = $input.all().map(i => i.json).filter(r => r && typeof r.message === 'string');
const attempts = rows.filter(r => r.message.startsWith('[KYC-REJECT]')).length;
const nextAttempt = attempts + 1;

const parsed = rej.parsed || {};

// Closed vocabulary. Nothing here originates from the model's own words.
const REASONS = {
  TAMPERED:   'the document looks edited or the details do not line up',
  EXPIRED:    'the document appears to have expired',
  UNREADABLE: 'we could not read it clearly enough to verify it',
  INVALID:    'we could not verify it as a valid document'
};

let expired = false;
if (parsed.expiryDate) {
  const t = Date.parse(parsed.expiryDate);
  if (!isNaN(t) && t < Date.now()) expired = true;
}

let reasonCode = 'INVALID';
if (parsed.tamperingDetected === true) reasonCode = 'TAMPERED';
else if (expired) reasonCode = 'EXPIRED';
else if (parsed.confidenceScore < 60) reasonCode = 'UNREADABLE';

const reason = REASONS[reasonCode];

const text = 'Hi ' + (rej.lead_name || 'there') + ', thanks for sending your document. '
  + 'Unfortunately we could not accept it: ' + reason + '. '
  + 'Could you please re-send a clear, well-lit photo showing the whole document with all four corners visible? '
  + '(Attempt ' + nextAttempt + ' of ' + MAX_ATTEMPTS + ')';

// 'parsed' is still passed through untouched. Record KYC (Rejected) reads
// documentType / fullName / confidenceScore off it and writes them to
// kyc_documents -- the RLS-protected table that nexus_retention_purge actually
// purges. The structured fields stay; only the free text stops travelling.
return [{ json: {
  attempts: attempts,
  nextAttempt: nextAttempt,
  maxAttempts: MAX_ATTEMPTS,
  withinLimit: nextAttempt <= MAX_ATTEMPTS,
  reasonCode: reasonCode,
  reason: reason,
  text: text,
  lead_email: rej.lead_email,
  lead_name: rej.lead_name,
  chat_id: rej.chat_id,
  parsed: parsed
} }];

parameters.text:
=:no_entry: *KYC blocked - human needed*

*Customer:* {{ $json.lead_name || 'Unknown' }}
*Email:* {{ $json.lead_email || 'n/a' }}
*WhatsApp:* {{ $json.chat_id || 'not provided' }}
*Why this reached you:* {{ $json.escalationReason }}
*Failed attempts:* {{ $json.countOk ? ($json.attempts + ' of ' + $json.maxAttempts) : 'not known — the count read failed, so this escalated rather than looping' }}

*Latest rejection reason:*
{{ $json.reason }}

The automated re-upload loop has stopped. Please contact this customer directly.

parameters.jsCode:
// This node sits ONLY on the public webhook branch.
// 'Called by Another Workflow' connects straight to the next node and never
// reaches here, so the trusted sub-workflow path is untouched by this guard.
//
// 'Verify JWT' runs with onError = continueRegularOutput, so a rejected token
// arrives as data rather than as a failed HTTP node. Supabase GET
// /auth/v1/user returns the user object on success; no .id means rejected.
//
// 2 Sep 2026: 'Tenant For JWT User' was inserted between Verify JWT and this
// node, and an HTTP node REPLACES the item, so the identity check reaches back
// to Verify JWT by name. The guard is otherwise unchanged.
let auth = {};
try { auth = $('Verify JWT').first().json || {}; } catch (e) { auth = {}; }
if (!auth.id) {
  // The '[NEXUS-UNATTRIBUTED]' prefix below is a contract with the NEXUS Error
  // Handler (iYJkh1kztWxZXDbT). An execution that failed BEFORE it authenticated
  // its caller belongs to no dealership, so that workflow omits tenant_id and
  // audit_log's own DEFAULT nexus_default_tenant_id() retains the row under the
  // quarantine tenant -- visible to nexus_quarantine_census(), unreadable by any
  // dealership -- instead of appending an anonymous stranger's row to ALBA CARS'
  // audit trail. Keep the marker at the START of the message: the handler tests
  // position 0, so a copy embedded in a request payload cannot trigger it.
  throw new Error('[NEXUS-UNATTRIBUTED] KYC upload rejected: unauthorized. A valid Supabase session token is required in the Authorization header.');
}

// Re-emit the ORIGINAL request untouched so the downstream node sees exactly
// the shape it saw before this guard was inserted. Nothing else had to change.
return $('ReceiveDocument').all();

// Archive the KYC document to Supabase Storage.
// Sits between the vision parse and the verdict branch on purpose: AML
// retention covers rejected and escalated documents too, not just approved.
const RETENTION_YEARS = 7;
const MAX_BYTES = 10 * 1024 * 1024;   // bucket file_size_limit

const p = $('Prepare Document').first().json;
const b64 = p.imageBase64;

const now = new Date();
const yyyy = String(now.getUTCFullYear());
const mm = String(now.getUTCMonth() + 1).padStart(2, '0');

const retain = new Date(now.getTime());
retain.setUTCFullYear(retain.getUTCFullYear() + RETENTION_YEARS);
const retain_until = retain.toISOString().slice(0, 10);   // column is DATE

const base = {
  auditResult: $json.auditResult,
  parsed: $json.parsed,
  retain_until: retain_until,
  storage_path: null,
  archive_skipped: true,
  archive_error: null,
};

if (!b64 || String(b64).length < 100) {
  base.archive_error = 'no image supplied — nothing to archive';
  return [{ json: base }];
}

const buf = Buffer.from(String(b64), 'base64');
if (buf.length > MAX_BYTES) {
  base.archive_error = 'image ' + buf.length + ' bytes exceeds the 10 MB bucket limit';
  return [{ json: base }];
}

// Sniff the real type -- the bucket only accepts jpeg/png/webp/pdf.
let ext = 'jpg', mime = 'image/jpeg';
if (buf[0] === 0x89 && buf[1] === 0x50) { ext = 'png'; mime = 'image/png'; }
else if (buf.slice(0, 4).toString('ascii') === '%PDF') { ext = 'pdf'; mime = 'application/pdf'; }
else if (buf.slice(0, 4).toString('ascii') === 'RIFF' &&
         buf.slice(8, 12).toString('ascii') === 'WEBP') { ext = 'webp'; mime = 'image/webp'; }

const uuid = (typeof crypto !== 'undefined' && crypto.randomUUID)
  ? crypto.randomUUID()
  : (Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 12));

// PRIVACY. The key used to carry an identity segment derived from the customer's
// email or phone number, e.g. kyc/ahmed_at_gmail.com/2026/08/<uuid>.jpg. Anyone
// able to list the bucket then read the customer list straight out of the key
// names without opening a file, and every log line, backup index or error
// message quoting a path leaked the same thing. The key is now non-identifying.
// kyc_documents.storage_path is the only link between a customer and their
// document, and that table is RLS-protected and is purged on schedule.
// nexus_retention_purge drives off those rows, not off the path structure, so
// deletion and gap-detection are unaffected.
const storage_path = 'kyc/' + yyyy + '/' + mm + '/' + uuid + '.' + ext;

return [{
  json: Object.assign({}, base, {
    storage_path: storage_path,
    archive_skipped: false,
    archive_error: null,
    mime_type: mime,
    size_bytes: buf.length,
  }),
  binary: { data: await this.helpers.prepareBinaryData(buf, uuid + '.' + ext, mime) },
}];

// Restore the audit payload for the verdict branch, and record whether the
// document actually reached Storage. The upload node runs with
// onError:continueRegularOutput so a failed archive never blocks the customer
// reply — but it must not silently claim a path that holds no object either.
// A NULL storage_path on a kyc_documents row is a visible compliance gap.
const a = $('Prepare Archive').first().json;
const r = $input.first().json || {};

const ok = !!(r.Key || r.Id);
let archive_error = a.archive_error || null;
if (!ok && !a.archive_skipped) {
  archive_error = 'storage upload failed: ' + JSON.stringify(r).substring(0, 300);
}

return [{ json: {
  auditResult: a.auditResult,
  parsed: a.parsed,
  storage_path: ok ? a.storage_path : null,
  retain_until: a.retain_until,
  archive_error: archive_error,
} }];

// Delivery Report - verify every claim the next node is about to make.
// The upstream sends run with onError:'continueRegularOutput'. A failure there
// is not an exception: n8n emits an item shaped { error: ... } on the main
// output and the run stays green. Nothing downstream ever looked at it, so the
// row written next asserted a send that may never have landed.
// The swallow is deliberate and stays. Only the unconditional claim goes.
const CLAIMED = [
  { node: 'WhatsApp: Request Re-upload', what: 'WhatsApp re-upload request to the customer', critical: true },
  { node: 'Count Previous KYC Rejections', what: 'previous-attempt count read from communication_logs', critical: false },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

const results = CLAIMED.map(check);

// 'Archive to Storage' swallows too, but a raw error item cannot tell the two
// cases apart, so judge it from 'Merge Archive Result' / 'Prepare Archive',
// which already do: a failed upload against a document we HAD is a compliance
// hole (the row below asserts a verdict on a document nobody retained), while
// a text-only submission had nothing to upload in the first place.
function grab(name) { try { return $(name).first().json || {}; } catch (e) { return null; } }
const merged = grab('Merge Archive Result');
const prep   = grab('Prepare Archive');
const ARCH   = { node: 'Archive to Storage', what: 'KYC document retained in Storage (7-year AML retention)' };

if (merged === null) {
  results.push({ ...ARCH, critical: true, ok: false, why: 'node did not run on this branch' });
} else if (merged.storage_path) {
  results.push({ ...ARCH, critical: true, ok: true });
} else if (prep && prep.archive_skipped === true) {
  results.push({ ...ARCH, critical: false, ok: false,
    why: 'nothing to archive: ' + String(merged.archive_error || 'no image supplied').slice(0, 200) });
} else {
  results.push({ ...ARCH, critical: true, ok: false,
    why: String(merged.archive_error || 'storage upload failed').slice(0, 300) });
}

const dropped = results.filter(r => !r.ok);
const fatal   = dropped.filter(r => r.critical);

const status = fatal.length   ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

return [{ json: {
  ...( $input.first().json || {} ),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' \u2014 ' + r.why),
    note: dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified',
  },
} }];

// Delivery Report - verify every claim the next node is about to make.
// The upstream sends run with onError:'continueRegularOutput'. A failure there
// is not an exception: n8n emits an item shaped { error: ... } on the main
// output and the run stays green. Nothing downstream ever looked at it, so the
// row written next asserted a send that may never have landed.
// The swallow is deliberate and stays. Only the unconditional claim goes.
const CLAIMED = [
  { node: 'Slack: KYC Escalation', what: 'Slack post asking a human to take over the KYC', critical: true },
  { node: 'Count Previous KYC Rejections', what: 'previous-attempt count read from communication_logs', critical: false },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

const results = CLAIMED.map(check);

// 'Archive to Storage' swallows too, but a raw error item cannot tell the two
// cases apart, so judge it from 'Merge Archive Result' / 'Prepare Archive',
// which already do: a failed upload against a document we HAD is a compliance
// hole (the row below asserts a verdict on a document nobody retained), while
// a text-only submission had nothing to upload in the first place.
function grab(name) { try { return $(name).first().json || {}; } catch (e) { return null; } }
const merged = grab('Merge Archive Result');
const prep   = grab('Prepare Archive');
const ARCH   = { node: 'Archive to Storage', what: 'KYC document retained in Storage (7-year AML retention)' };

if (merged === null) {
  results.push({ ...ARCH, critical: true, ok: false, why: 'node did not run on this branch' });
} else if (merged.storage_path) {
  results.push({ ...ARCH, critical: true, ok: true });
} else if (prep && prep.archive_skipped === true) {
  results.push({ ...ARCH, critical: false, ok: false,
    why: 'nothing to archive: ' + String(merged.archive_error || 'no image supplied').slice(0, 200) });
} else {
  results.push({ ...ARCH, critical: true, ok: false,
    why: String(merged.archive_error || 'storage upload failed').slice(0, 300) });
}

const dropped = results.filter(r => !r.ok);
const fatal   = dropped.filter(r => r.critical);

const status = fatal.length   ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

