=:no_entry: *KYC blocked - human needed*

*Customer:* {{ $json.lead_name || 'Unknown' }}
*Email:* {{ $json.lead_email || 'n/a' }}
*WhatsApp:* {{ $json.chat_id || 'not provided' }}
*Why this reached you:* {{ $json.escalationReason }}
*Failed attempts:* {{ $json.countOk ? ($json.attempts + ' of ' + $json.maxAttempts) : 'not known — the count read failed, so this escalated rather than looping' }}

*Latest rejection reason:*
{{ $json.reason }}

The automated re-upload loop has stopped. Please contact this customer directly.

parameters.jsCode:
// This node sits ONLY on the public webhook branch.
// 'Called by Another Workflow' connects straight to the next node and never
// reaches here, so the trusted sub-workflow path is untouched by this guard.
//
// 'Verify JWT' runs with onError = continueRegularOutput, so a rejected token
// arrives as data rather than as a failed HTTP node. Supabase GET
// /auth/v1/user returns the user object on success; no .id means rejected.
//
// 2 Sep 2026: 'Tenant For JWT User' was inserted between Verify JWT and this
// node, and an HTTP node REPLACES the item, so the identity check reaches back
// to Verify JWT by name. The guard is otherwise unchanged.
let auth = {};
try { auth = $('Verify JWT').first().json || {}; } catch (e) { auth = {}; }
if (!auth.id) {
  // The '[NEXUS-UNATTRIBUTED]' prefix below is a contract with the NEXUS Error
  // Handler (iYJkh1kztWxZXDbT). An execution that failed BEFORE it authenticated
  // its caller belongs to no dealership, so that workflow omits tenant_id and
  // audit_log's own DEFAULT nexus_default_tenant_id() retains the row under the
  // quarantine tenant -- visible to nexus_quarantine_census(), unreadable by any
  // dealership -- instead of appending an anonymous stranger's row to ALBA CARS'
  // audit trail. Keep the marker at the START of the message: the handler tests
  // position 0, so a copy embedded in a request payload cannot trigger it.
  throw new Error('[NEXUS-UNATTRIBUTED] KYC upload rejected: unauthorized. A valid Supabase session token is required in the Authorization header.');
}

// Re-emit the ORIGINAL request untouched so the downstream node sees exactly
// the shape it saw before this guard was inserted. Nothing else had to change.
return $('ReceiveDocument').all();

// Archive the KYC document to Supabase Storage.
// Sits between the vision parse and the verdict branch on purpose: AML
// retention covers rejected and escalated documents too, not just approved.
const RETENTION_YEARS = 7;
const MAX_BYTES = 10 * 1024 * 1024;   // bucket file_size_limit

const p = $('Prepare Document').first().json;
const b64 = p.imageBase64;

const now = new Date();
const yyyy = String(now.getUTCFullYear());
const mm = String(now.getUTCMonth() + 1).padStart(2, '0');

const retain = new Date(now.getTime());
retain.setUTCFullYear(retain.getUTCFullYear() + RETENTION_YEARS);
const retain_until = retain.toISOString().slice(0, 10);   // column is DATE

const base = {
  auditResult: $json.auditResult,
  parsed: $json.parsed,
  retain_until: retain_until,
  storage_path: null,
  archive_skipped: true,
  archive_error: null,
};

if (!b64 || String(b64).length < 100) {
  base.archive_error = 'no image supplied — nothing to archive';
  return [{ json: base }];
}

const buf = Buffer.from(String(b64), 'base64');
if (buf.length > MAX_BYTES) {
  base.archive_error = 'image ' + buf.length + ' bytes exceeds the 10 MB bucket limit';
  return [{ json: base }];
}

// Sniff the real type -- the bucket only accepts jpeg/png/webp/pdf.
let ext = 'jpg', mime = 'image/jpeg';
if (buf[0] === 0x89 && buf[1] === 0x50) { ext = 'png'; mime = 'image/png'; }
else if (buf.slice(0, 4).toString('ascii') === '%PDF') { ext = 'pdf'; mime = 'application/pdf'; }
else if (buf.slice(0, 4).toString('ascii') === 'RIFF' &&
         buf.slice(8, 12).toString('ascii') === 'WEBP') { ext = 'webp'; mime = 'image/webp'; }

const uuid = (typeof crypto !== 'undefined' && crypto.randomUUID)
  ? crypto.randomUUID()
  : (Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 12));

// PRIVACY. The key used to carry an identity segment derived from the customer's
// email or phone number, e.g. kyc/ahmed_at_gmail.com/2026/08/<uuid>.jpg. Anyone
// able to list the bucket then read the customer list straight out of the key
// names without opening a file, and every log line, backup index or error
// message quoting a path leaked the same thing. The key is now non-identifying.
// kyc_documents.storage_path is the only link between a customer and their
// document, and that table is RLS-protected and is purged on schedule.
// nexus_retention_purge drives off those rows, not off the path structure, so
// deletion and gap-detection are unaffected.
const storage_path = 'kyc/' + yyyy + '/' + mm + '/' + uuid + '.' + ext;

return [{
  json: Object.assign({}, base, {
    storage_path: storage_path,
    archive_skipped: false,
    archive_error: null,
    mime_type: mime,
    size_bytes: buf.length,
  }),
  binary: { data: await this.helpers.prepareBinaryData(buf, uuid + '.' + ext, mime) },
}];

// Restore the audit payload for the verdict branch, and record whether the
// document actually reached Storage. The upload node runs with
// onError:continueRegularOutput so a failed archive never blocks the customer
// reply — but it must not silently claim a path that holds no object either.
// A NULL storage_path on a kyc_documents row is a visible compliance gap.
const a = $('Prepare Archive').first().json;
const r = $input.first().json || {};

const ok = !!(r.Key || r.Id);
let archive_error = a.archive_error || null;
if (!ok && !a.archive_skipped) {
  archive_error = 'storage upload failed: ' + JSON.stringify(r).substring(0, 300);
}

return [{ json: {
  auditResult: a.auditResult,
  parsed: a.parsed,
  storage_path: ok ? a.storage_path : null,
  retain_until: a.retain_until,
  archive_error: archive_error,
} }];

// Delivery Report - verify every claim the next node is about to make.
// The upstream sends run with onError:'continueRegularOutput'. A failure there
// is not an exception: n8n emits an item shaped { error: ... } on the main
// output and the run stays green. Nothing downstream ever looked at it, so the
// row written next asserted a send that may never have landed.
// The swallow is deliberate and stays. Only the unconditional claim goes.
const CLAIMED = [
  { node: 'WhatsApp: Request Re-upload', what: 'WhatsApp re-upload request to the customer', critical: true },
  { node: 'Count Previous KYC Rejections', what: 'previous-attempt count read from communication_logs', critical: false },
];

function check(c) {
